#include <cmath>

struct Point2f { float x, y; };
struct Vector3f { float x, y, z; };

Vector3f UniformSampleHemisphere(const Point2f &u) {
    float z = u.x;
    float r = std::sqrt(std::max(0.0f, 1.0f - z * z));
    float phi = 2 * M_PI * u.y;
    float x = r * std::cos(phi);
    float y = r * std::sin(phi);
    return {x, y, z};
}

